import{Z as r,e as t,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const u=JSON.parse('{"title":"Migrating from Freeform","description":"","frontmatter":{},"headers":[],"relativePath":"guides/migrations-upgrades/migrating-from-freeform.md","filePath":"guides/migrations-upgrades/migrating-from-freeform.md","lastUpdated":1782532814000}'),a={name:"guides/migrations-upgrades/migrating-from-freeform.md"};function n(s,e,l,d,m,f){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="migrating-from-freeform" tabindex="-1">Migrating from Freeform <a class="header-anchor" href="#migrating-from-freeform" aria-label="Permalink to &quot;Migrating from Freeform&quot;">​</a></h1><p>If your Craft site runs <a href="https://docs.solspace.com/craft/freeform/v5/" target="_blank" rel="noreferrer">Solspace Freeform</a>, Formie&#39;s migration tool copies forms, email notifications, and submissions into Formie without modifying Freeform data. This guide walks through the migration UI, handle collisions, unsupported fields, and what to verify before switching production forms to Formie.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Formie installed</li><li>Freeform still installed and <strong>enabled</strong> (required for the migration screen to appear)</li><li>Backup of database and <code>storage/</code> before migrating production</li></ul><h2 id="supported-freeform-versions" tabindex="-1">Supported Freeform Versions <a class="header-anchor" href="#supported-freeform-versions" aria-label="Permalink to &quot;Supported Freeform Versions&quot;">​</a></h2><ul><li>Freeform 3.x</li><li>Freeform 4.x</li><li>Freeform 5.x</li></ul><h2 id="before-you-migrate" tabindex="-1">Before You Migrate <a class="header-anchor" href="#before-you-migrate" aria-label="Permalink to &quot;Before You Migrate&quot;">​</a></h2><ol><li><strong>Audit forms</strong> — list handles, integrations, and payment flows in Freeform</li><li><strong>Note unsupported fields</strong> — see below; plan manual rebuilds</li><li><strong>Install Formie</strong> on staging first; keep Freeform enabled until verification completes</li><li><strong>Review notifications</strong> — Freeform admin notifications map to Formie email notifications; test deliverability after migration</li><li><strong>Plan front-end cutover</strong> — replace Freeform render tags with <code>craft.formie.renderForm()</code> or headless packages</li></ol><h2 id="run-the-migration" tabindex="-1">Run the Migration <a class="header-anchor" href="#run-the-migration" aria-label="Permalink to &quot;Run the Migration&quot;">​</a></h2><ol><li>Navigate to <strong>Formie → Settings → Migrations → Freeform</strong></li><li>Select the Freeform forms to migrate</li><li>Click <strong>Migrate Forms</strong></li><li>Review the results screen — forms, notifications, and submissions copied, plus any errors</li></ol><p>Your Freeform data remains untouched. Migration creates <strong>new</strong> Formie forms.</p><h2 id="handle-collisions" tabindex="-1">Handle Collisions <a class="header-anchor" href="#handle-collisions" aria-label="Permalink to &quot;Handle Collisions&quot;">​</a></h2><p>If Formie already has a form with handle <code>contactForm</code> and Freeform also has <code>contactForm</code>, the migrated form becomes <code>contactForm1</code> (numeric suffix).</p><p>Rename handles in the Formie builder after migration if you need cleaner names — update templates and integrations that reference the handle.</p><h2 id="unsupported-fields" tabindex="-1">Unsupported Fields <a class="header-anchor" href="#unsupported-fields" aria-label="Permalink to &quot;Unsupported Fields&quot;">​</a></h2><p>The following Freeform field types are <strong>not</strong> migrated and require manual recreation in Formie:</p><table tabindex="0"><thead><tr><th>Freeform field</th><th>Notes</th></tr></thead><tbody><tr><td>Payments (Pro)</td><td>Rebuild with Formie <a href="/fields/payment">Payment</a> + <a href="/integrations/payments/stripe">Stripe</a></td></tr><tr><td>Opinion Scale (Pro)</td><td>Use Radio, Dropdown, or custom field</td></tr><tr><td>Rating (Pro)</td><td>Use custom field or third-party</td></tr><tr><td>Regex (Pro)</td><td>Use validation rules on Single-Line Text</td></tr><tr><td>Rich Text (Pro)</td><td>Use Multi-Line Text with rich text enabled</td></tr><tr><td>Dynamic Recipient</td><td>Use Recipients field or notification conditions</td></tr><tr><td>Mailing List</td><td>Use email marketing integration</td></tr><tr><td>Recaptcha</td><td>Enable Turnstile/reCAPTCHA under <strong>Settings → Spam Protection</strong></td></tr></tbody></table><p>Submissions for unsupported fields may lose that column&#39;s data — export from Freeform first if you need archives.</p><h2 id="after-migration-checklist" tabindex="-1">After Migration Checklist <a class="header-anchor" href="#after-migration-checklist" aria-label="Permalink to &quot;After Migration Checklist&quot;">​</a></h2><ul><li>Open each migrated form in the builder — verify field layout and handles</li><li>Reconfigure captchas on <strong>Settings → Spam Protection</strong> and per form</li><li>Reconnect CRM/marketing integrations (OAuth tokens do not copy)</li><li>Update Twig templates from Freeform tags to Formie render helpers</li><li>Update headless/GraphQL clients to Formie endpoints</li><li>Test submit on staging — notifications, integrations, spam screening</li><li>Compare submission counts Freeform vs Formie for migrated forms</li><li>Run <a href="/guides/migrations-upgrades/template-compatibility-audit-after-upgrade">template compatibility audit</a> if you are upgrading Formie at the same time</li></ul><h2 id="cutover-strategy" tabindex="-1">Cutover Strategy <a class="header-anchor" href="#cutover-strategy" aria-label="Permalink to &quot;Cutover Strategy&quot;">​</a></h2><p><strong>Parallel run (recommended):</strong> Keep Freeform forms on hidden URLs while Formie forms go live on production pages. Compare submissions for a week, then disable Freeform render tags.</p><p><strong>Hard cutover:</strong> Swap templates in one deploy during low traffic. Have Freeform export/submission archive ready.</p><p>Disable or uninstall Freeform only after you are confident Formie owns all active forms.</p><h2 id="after-migration" tabindex="-1">After Migration <a class="header-anchor" href="#after-migration" aria-label="Permalink to &quot;After Migration&quot;">​</a></h2><p>Migrated forms land as standard Formie forms — submission guards, spam settings, client events, and database-backed save-and-continue apply immediately. Review:</p><ul><li><a href="/forms/spam-protection">Spam Protection</a> — legacy Freeform honeypot maps to submission guards</li><li><a href="/forms/submission-screening">Submission Screening</a> — understand the <code>screen</code> stage</li><li><a href="/get-started/upgrading-from-v3">Upgrading From v3</a> if you are also upgrading from an older Formie install</li></ul>',27)])])}const c=r(a,[["render",n]]);export{u as __pageData,c as default};
